<script setup lang="ts">
import {formatUsageTokens as token, formatUsageWithShare, formatUsageShare, hasChartableComposition} from '../../utils/usageTokenFormat'
import {nextTick,onBeforeUnmount,onMounted,ref} from 'vue'
import {useUsageText} from '../../composables/useUsageText'
const tr=useUsageText(),panel=ref<HTMLElement|null>(null),value=ref<any>(null),kind=ref('tokens'),context=ref('');let anchor:HTMLElement|null=null;let sequence=0
const colors=['var(--accent)','#a0b6ec','#16805e','#7caa8c']
const fmt=(n:any)=>n===null||n===undefined?'—':BigInt(n).toLocaleString()
function close(){++sequence;if(!value.value)return;if(panel.value?.matches(':popover-open'))panel.value.hidePopover();anchor?.setAttribute('aria-pressed','false');if(anchor?.isConnected)anchor.focus({preventScroll:true});value.value=null;anchor=null}
async function open(record:any,event:Event|undefined,type:string,label:string){if(value.value)close();const request=++sequence;anchor=(event?.currentTarget as HTMLElement)??document.activeElement as HTMLElement;value.value=record;kind.value=type;context.value=label;const target=anchor?.closest('dialog')??document.querySelector('.tokens-page')??document.body;if(panel.value&&panel.value.parentNode!==target)target.append(panel.value);await nextTick();if(request!==sequence)return;panel.value?.showPopover();anchor?.setAttribute('aria-pressed','true');const box=panel.value!.getBoundingClientRect(),at=anchor?.getBoundingClientRect();panel.value!.style.left=Math.max(12,Math.min(innerWidth-box.width-12,(at?.left??12)+(at?.width??0)/2-box.width/2))+'px';panel.value!.style.top=Math.max(12,Math.min(innerHeight-box.height-12,(at?.top??12)-box.height-12))+'px';panel.value!.querySelector('button')?.focus({preventScroll:true})}
function key(event:KeyboardEvent){if(event.key==='Escape'&&value.value){event.preventDefault();event.stopImmediatePropagation();close()}}
function outside(event:PointerEvent){if(value.value&&!panel.value?.contains(event.target as Node)&&!anchor?.contains(event.target as Node))close()}
onMounted(()=>{document.addEventListener('keydown',key,true);document.addEventListener('pointerdown',outside,true)})
onBeforeUnmount(()=>{document.removeEventListener('keydown',key,true);document.removeEventListener('pointerdown',outside,true);panel.value?.remove()})
defineExpose({open,close})
</script>
<template><div ref="panel" popover="manual" class="pu pu-period-popover" role="dialog" :aria-label="kind==='calls'?tr('调用周期'):tr('周期用量')"><template v-if="value"><header><div><small>{{context}} · UTC</small><h3>{{value.date??value.bucket_start?.slice(0,10)}} — {{value.end_exclusive?.slice(0,10)??value.date}}</h3></div><button :aria-label="tr('关闭')" @click="close">×</button></header><span v-if="value.partial_period" class="pu-period-badge">{{tr('非完整周期')}}</span><template v-if="kind==='calls'"><div v-for="[k,label] in [['tools','工具调用'],['mcp','MCP调用'],['skills','Skill执行']]" :key="k" class="pu-kv"><span>{{tr(label)}}</span><b>{{fmt(value[k])}}</b></div><p class="pu-note">{{tr('MCP已含在工具中；Skill独立。当前范围不变。')}}</p></template><template v-else><div class="pu-total"><span>{{tr('总量')}}</span><strong>{{token(value.total)}} <small>Token</small></strong></div><div v-if="hasChartableComposition(value)" class="pu-composition-bar"><i v-for="(k,i) in ['input','output','cache_read','cache_create']" :key="k" :style="{width:formatUsageShare(value[k],value.total),background:colors[i]}"/></div><div v-for="[k,label] in [['input','输入'],['output','输出'],['cache_read','缓存读取'],['cache_create','缓存写入'],['requests','模型请求']]" :key="k" class="pu-kv"><span>{{tr(label)}}</span><b>{{k==='requests'?fmt(value[k]):formatUsageWithShare(value[k], value.total)}}</b></div></template><p class="pu-note">{{tr('热力图独立最近90天；查看周期不改变统计范围。')}}</p><p class="pu-note">{{tr('缺口不补零')}}</p></template></div></template>
<style scoped>.pu-period-popover{width:min(332px,calc(100vw - 24px));inset:auto;position:fixed;background:var(--panel);color:var(--ink);margin:0;max-height:calc(100dvh - 24px);z-index:3000}.pu-period-popover header{display:flex;align-items:start;justify-content:space-between}.pu-period-popover button{border:0;background:var(--soft);color:inherit;border-radius:50%;width:32px;height:32px}.pu-period-popover h3{margin:6px 0}.pu-period-popover .pu-total{margin:16px 0}</style>
